namespace Atc.Rest.Api.Generator.Cli.Tests.Services.Migration;

public sealed class GeneratedCodeCleanerTests : IDisposable
{
    private const string GeneratedModel = """
        //------------------------------------------------------------------------------
        // This code was auto-generated by ApiGenerator 2.0.360.0.
        //
        // Changes to this file may cause incorrect behavior and will be lost if
        // the code is regenerated.
        //------------------------------------------------------------------------------
        namespace Demo.Api.Generated.Contracts.Accounts;

        [GeneratedCode("ApiGenerator", "2.0.360.0")]
        public class Account
        {
        }
        """;

    private const string HandWrittenModel = """
        namespace Demo.Api.Generated.Contracts.Accounts;

        public record AccountCallbackResponse(string Id);
        """;

    private readonly string root = Path.Combine(Path.GetTempPath(), "atc-cleaner-" + Guid.NewGuid().ToString("N"));

    [Fact]
    public void CleanServerProject_KeepsHandWrittenFilesInTheGeneratedFolders()
    {
        var generated = Write("Contracts/Accounts/Models/Account.cs", GeneratedModel);
        var handWritten = Write("Contracts/Accounts/Models/AccountCallbackResponse.cs", HandWrittenModel);

        var result = GeneratedCodeCleaner.CleanServerProject(root);

        Assert.False(File.Exists(generated));
        Assert.True(File.Exists(handWritten));
        Assert.Equal(HandWrittenModel, File.ReadAllText(handWritten));
        Assert.Equal([handWritten], result.PreservedFiles);
    }

    [Fact]
    public void CleanServerProject_DeletesAFolderThatHoldsOnlyGeneratedFiles()
    {
        Write("Contracts/Accounts/Models/Account.cs", GeneratedModel);
        Write("Endpoints/AccountsController.cs", GeneratedModel);
        Write("Resources/ApiSpecification.yaml", "openapi: 3.0.0");

        var result = GeneratedCodeCleaner.CleanServerProject(root);

        Assert.False(Directory.Exists(Path.Combine(root, "Contracts")));
        Assert.False(Directory.Exists(Path.Combine(root, "Endpoints")));
        Assert.False(Directory.Exists(Path.Combine(root, "Resources")));
        Assert.Empty(result.PreservedFiles);
        Assert.Equal(3, result.TotalItemsDeleted);
    }

    [Fact]
    public void CleanServerProject_DryRun_ReportsWithoutDeleting()
    {
        var generated = Write("Contracts/Accounts/Models/Account.cs", GeneratedModel);
        var handWritten = Write("Contracts/Accounts/Models/AccountCallbackResponse.cs", HandWrittenModel);

        var result = GeneratedCodeCleaner.CleanServerProject(root, dryRun: true);

        Assert.True(File.Exists(generated));
        Assert.True(File.Exists(handWritten));
        Assert.Equal([handWritten], result.PreservedFiles);
        Assert.Equal(1, result.TotalItemsDeleted);
    }

    public void Dispose()
    {
        if (Directory.Exists(root))
        {
            Directory.Delete(root, recursive: true);
        }
    }

    private string Write(
        string relativePath,
        string content)
    {
        var path = Path.Combine(root, relativePath.Replace('/', Path.DirectorySeparatorChar));
        Directory.CreateDirectory(Path.GetDirectoryName(path)!);
        File.WriteAllText(path, content);
        return path;
    }
}